// This is a complete desired snapshot for one edge process.  A missing row is
// therefore an explicit authorization absence, while a failed query must
// leave the edge's last-known-good registry untouched.
// A tunnel on the endpoint engine (PLAN 3a step 4): its route rides on the agent's runtime carrier
// to this edge. The carrier identity (tunnel, connector, session, generations, config hash) is the
// runtime carrier's, exactly as the edge admitted it; the route id names the tunnel route. Only an
// edge process that serves tunnel endpoints is told.
func (q *Queries) ListTunnelEdgeRouteAssignmentsForNodeV1(ctx context.Context, arg ListTunnelEdgeRouteAssignmentsForNodeV1Params) ([]ListTunnelEdgeRouteAssignmentsForNodeV1Row, error) {
	rows, err := q.db.Query(ctx, listTunnelEdgeRouteAssignmentsForNodeV1, arg.EdgeNodeID, arg.EdgeProcessEpoch, arg.Now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListTunnelEdgeRouteAssignmentsForNodeV1Row
	for rows.Next() {
		var i ListTunnelEdgeRouteAssignmentsForNodeV1Row
		if err := rows.Scan(
			&i.AssignmentID,
			&i.RouteID,
			&i.AssignmentGeneration,
			&i.RouteRevision,
			&i.AccountID,
			&i.TunnelID,
			&i.ConnectorID,
			&i.HostID,
			&i.MachineIdentityPublicKey,
			&i.MachineIdentityThumbprint,
			&i.ConnectorGeneration,
			&i.ConnectorSessionID,
			&i.ConnectorProcessGeneration,
			&i.ConfigGeneration,
			&i.ConfigContentHash,
			&i.AccessMode,
			&i.ViewerPolicyGeneration,
			&i.RouteGeneration,
			&i.EdgeNodeID,
			&i.EdgeProcessEpoch,
			&i.EdgeFailureDomain,
			&i.Kind,
			&i.PublicHost,
			&i.MatchType,
			&i.MatchHostname,
			&i.WildcardSuffix,
			&i.PathPrefix,
			&i.Priority,
			&i.Protocol,
			&i.PublicTcpListenerID,
			&i.PublicTcpPort,
			&i.OriginScheme,
			&i.PreserveHost,
			&i.HostOverride,
			&i.ScopedDomainHostname,
			&i.ScopedDomainMatchType,
			&i.DomainBindings,
			&i.State,
			&i.ObservedState,
			&i.RouteDesiredState,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

